changeSet.sql:
ALTER TABLE sch_third_party_data.aer_staging
ADD COLUMN import_status VARCHAR(255);

UPDATE sch_third_party_data.aer_staging
SET import_status = CASE
    WHEN imported_on IS NULL THEN 'NEW'
    ELSE 'IMPORTED'
END;

ALTER TABLE sch_third_party_data.aer_staging
ALTER COLUMN import_status SET NOT NULL;

